type PruneWorkspaces500JSONResponse struct{ InternalErrorJSONResponse }

func (response PruneWorkspaces500JSONResponse) VisitPruneWorkspacesResponse(w http.ResponseWriter) error {

	var buf bytes.Buffer
	if err := json.NewEncoder(&buf).Encode(response); err != nil {
		return err
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(500)
	_, err := buf.WriteTo(w)
	return err
}

